function getCart(){return JSON.parse(localStorage.getItem("cart"))||[]}function generateOrderId(){return"ORD-"+Math.random().toString(36).substring(2,8).toUpperCase()}function calculateTotals(t){let e=t.reduce((t,e)=>t+e.price*e.quantity,0),n=t.length>0?50:0,o=.05*e;return{subtotal:e,shipping:n,tax:o,total:e+n+o}}function showToast(t,e="success"){let n=document.getElementById("toast");n.textContent=t,n.className=`toast ${e} show`,setTimeout(()=>n.classList.remove("show"),3e3)}function renderCheckout(){let t=getCart(),e=document.getElementById("checkout-items-list");if(0===t.length){window.location.href="cart.html";return}e.innerHTML="",t.forEach(t=>{let n=document.createElement("div");n.classList.add("checkout-item"),n.innerHTML=`
    <img src="${t.image}" alt="${t.title}" />
    <div class="checkout-item-details">
        <h3>${t.title}</h3>
        <p>Size: <strong>${t.size}</strong> | Color: <strong>${t.color||"Default"}</strong></p>
        <p>Quantity: <strong>${t.quantity}</strong></p>
    </div>
    <div class="checkout-item-price">
        Rs. ${(t.price*t.quantity).toFixed(2)}
    </div>
`,e.appendChild(n)});let{subtotal:n,shipping:o,tax:i,total:l}=calculateTotals(t);document.getElementById("co-subtotal").textContent=`Rs. ${n.toFixed(2)}`,document.getElementById("co-shipping").textContent=`Rs. ${o.toFixed(2)}`,document.getElementById("co-tax").textContent=`Rs. ${i.toFixed(2)}`,document.getElementById("co-total").textContent=`Rs. ${l.toFixed(2)}`}function showConfirmation(t){let{total:e}=calculateTotals(t),n=generateOrderId();document.getElementById("checkout-section").style.display="none",document.getElementById("confirmation-section").style.display="block",document.getElementById("order-id-text").textContent=n,document.getElementById("confirmation-total-amount").textContent=`Rs. ${e.toFixed(2)}`;let o=document.getElementById("confirmation-items-list");o.innerHTML="",t.forEach(t=>{let e=document.createElement("div");e.classList.add("confirmation-item"),e.innerHTML=`
    <img src="${t.image}" alt="${t.title}" />
    <div>
        <p><strong>${t.title}</strong></p>
        <p>Size: ${t.size} | Color: ${t.color||"Default"} | Qty: ${t.quantity}</p>
    </div>
    <p class="conf-item-price">Rs. ${(t.price*t.quantity).toFixed(2)}</p>
`,o.appendChild(e)}),localStorage.removeItem("cart");let i=document.querySelector("#cart-count");i&&(i.textContent="0",i.style.display="none"),window.scrollTo({top:0,behavior:"smooth"})}console.log("Checkout page JS connected"),document.addEventListener("DOMContentLoaded",()=>{renderCheckout(),document.getElementById("place-order-btn").addEventListener("click",()=>{let t=getCart();t.length>0&&showConfirmation(t)})});